import React, { useRef, useState } from 'react';
import { Maximize2, Pause, Play, Volume2, VolumeX } from 'lucide-react';

type QuickPayVideoPlayerProps = {
  src: string;
  poster?: string;
  title: string;
  className?: string;
  cover?: boolean;
};

const formatTime = (seconds: number) => {
  if (!Number.isFinite(seconds)) return '0:00';
  const minutes = Math.floor(seconds / 60);
  return `${minutes}:${Math.floor(seconds % 60).toString().padStart(2, '0')}`;
};

export const QuickPayVideoPlayer = ({
  src,
  poster,
  title,
  className = '',
  cover = false,
}: QuickPayVideoPlayerProps) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [playing, setPlaying] = useState(false);
  const [muted, setMuted] = useState(true);
  const [duration, setDuration] = useState(0);
  const [currentTime, setCurrentTime] = useState(0);

  const togglePlayback = async () => {
    const video = videoRef.current;
    if (!video) return;
    if (video.paused) {
      try {
        await video.play();
      } catch {
        setPlaying(false);
      }
    } else {
      video.pause();
    }
  };

  const toggleMute = () => {
    const video = videoRef.current;
    if (!video) return;
    video.muted = !video.muted;
    setMuted(video.muted);
  };

  const enterFullscreen = async () => {
    const video = videoRef.current;
    if (!video) return;
    if (video.requestFullscreen) await video.requestFullscreen();
    else if ('webkitEnterFullscreen' in video) (video as HTMLVideoElement & { webkitEnterFullscreen: () => void }).webkitEnterFullscreen();
  };

  return (
    <div
      className={`group relative isolate overflow-hidden rounded-[1.75rem] border border-white/10 bg-[#050505] shadow-[0_24px_70px_rgba(0,0,0,0.38),inset_0_1px_0_rgba(255,255,255,0.08)] ${className}`}
    >
      <video
        ref={videoRef}
        src={src}
        poster={poster}
        preload="metadata"
        playsInline
        muted={muted}
        autoPlay={cover}
        loop={cover}
        aria-label={title}
        onClick={() => void togglePlayback()}
        onDoubleClick={() => void enterFullscreen()}
        onPlay={() => setPlaying(true)}
        onPause={() => setPlaying(false)}
        onEnded={() => setPlaying(false)}
        onLoadedMetadata={(event) => setDuration(event.currentTarget.duration)}
        onDurationChange={(event) => setDuration(event.currentTarget.duration)}
        onTimeUpdate={(event) => setCurrentTime(event.currentTarget.currentTime)}
        className={`h-full w-full cursor-pointer ${cover ? 'object-cover' : 'object-contain'}`}
      />

      <div className="pointer-events-none absolute inset-0 bg-gradient-to-t from-black/70 via-transparent to-black/20" />
      <div className="pointer-events-none absolute inset-0 rounded-[inherit] ring-1 ring-inset ring-white/[0.08]" />

      {!playing && (
        <button
          type="button"
          onClick={() => void togglePlayback()}
          aria-label="Play video"
          className="absolute left-1/2 top-1/2 z-20 flex h-16 w-16 -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-full border border-white/20 bg-black/55 text-white shadow-[0_12px_35px_rgba(0,0,0,0.45)] backdrop-blur-xl transition duration-300 hover:scale-105 hover:bg-black/70 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/80"
        >
          <Play className="ml-1 h-6 w-6 fill-current" />
        </button>
      )}

      <div className="pointer-events-none absolute inset-x-4 top-4 z-10 flex">
        <span className="max-w-[75%] truncate rounded-full border border-white/10 bg-black/35 px-3 py-1.5 text-[10px] font-semibold tracking-wide text-white/75 shadow-lg backdrop-blur-xl">
          {title}
        </span>
      </div>

      <div className="absolute inset-x-3 bottom-3 z-20 flex items-center gap-2 rounded-2xl border border-white/10 bg-black/55 p-2 text-white shadow-[0_10px_30px_rgba(0,0,0,0.32)] backdrop-blur-xl sm:inset-x-4 sm:bottom-4">
        <button
          type="button"
          onClick={() => void togglePlayback()}
          aria-label={playing ? 'Pause video' : 'Play video'}
          className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-white/10 transition hover:bg-white/20 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/70"
        >
          {playing ? <Pause className="h-4 w-4 fill-current" /> : <Play className="h-4 w-4 fill-current" />}
        </button>

        <div className="flex min-w-0 flex-1 items-center gap-2">
          <input
            type="range"
            min="0"
            max={duration || 0}
            step="0.1"
            value={Math.min(currentTime, duration || 0)}
            aria-label="Video progress"
            onChange={(event) => {
              const nextTime = Number(event.target.value);
              if (videoRef.current) videoRef.current.currentTime = nextTime;
              setCurrentTime(nextTime);
            }}
            className="h-1.5 min-w-0 flex-1 cursor-pointer accent-white"
          />
          <span className="hidden shrink-0 font-mono text-[9px] tabular-nums text-white/60 sm:block">
            {formatTime(currentTime)} / {formatTime(duration)}
          </span>
        </div>

        <button
          type="button"
          onClick={toggleMute}
          aria-label={muted ? 'Unmute video' : 'Mute video'}
          className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl transition hover:bg-white/10 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/70"
        >
          {muted ? <VolumeX className="h-4 w-4" /> : <Volume2 className="h-4 w-4" />}
        </button>
        <button
          type="button"
          onClick={() => void enterFullscreen()}
          aria-label="Open video fullscreen"
          className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl transition hover:bg-white/10 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/70"
        >
          <Maximize2 className="h-4 w-4" />
        </button>
      </div>
    </div>
  );
};
